};

const CH_MAP = {
  TYPE_FACEBOOK: 'Messenger', TYPE_SMS: 'SMS', TYPE_PHONE: 'SMS',
  TYPE_INSTAGRAM: 'Instagram', TYPE_WHATSAPP: 'Messenger',
  TYPE_LIVE_CHAT: 'SMS', TYPE_WEBCHAT: 'SMS', TYPE_VIBER: 'Viber'
};

const opps = ($input.all()[0].json.opportunities || []);
const counts = {};
const bookings = [];
let paymentTotal = 0;

const PAYMENT_STAGES = ['FaceCard / For Downpayment','Downpayment verification','Full Payment Confirmation'];
const NOW = Date.now();
const MONTH_START = new Date(); MONTH_START.setDate(1); MONTH_START.setHours(0,0,0,0);

opps.forEach(o => {
  const stage = STAGE_MAP[o.pipelineStageId] || 'Unknown';
  counts[stage] = (counts[stage] || 0) + 1;
  if (PAYMENT_STAGES.includes(stage)) paymentTotal += (o.monetaryValue || 0);
  if (bookings.length < 30) {
    bookings.push({
      id: 'HS-' + o.id.slice(-4).toUpperCase(),
      ghlId: o.id,
      client: o.contact?.name || o.name || 'Client',
      service: o.name || 'Service',
      city: o.contact?.city || '',
      stage,
      when: o.createdAt ? new Date(o.createdAt).toLocaleDateString('en-PH', {month:'short',day:'numeric'}) : '',
      amount: o.monetaryValue || 0,
      channel: CH_MAP[o.contact?.type] || 'SMS',
      hp: null,
      note: ''
    });
  }
});

const completedThisMonth = opps.filter(o =>
  STAGE_MAP[o.pipelineStageId] === 'Job Completed' &&
  new Date(o.updatedAt) >= MONTH_START
).length;

return [{ json: { counts, bookings, paymentTotal, completedThisMonth, total: opps.length, updatedAt: new Date().toISOString() } }];
